div.script:

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('gameOverlay');
const scoreVal = document.getElementById('scoreVal');
const highScoreVal = document.getElementById('highScoreVal');

// Always ensure the Back button links back via jsDelivr with fresh cache bypass
document.getElementById('backToHubBtn').href = 'https://cdn.jsdelivr.net/gh/mathbuddies/leawoodmiddle@main/index.svg?v=' + Date.now();

let isPlaying = false;
let score = 0;
let highScore = parseInt(localStorage.getItem('eagle_pe_high') || '0');
highScoreVal.textContent = highScore;

let player = { x: 400, y: 440, radius: 18, speed: 7, dx: 0 };
let dodgeballs = [];
let items = [];
let frameCount = 0;
let keys = {};

window.addEventListener('keydown', (e) => { keys[e.key] = true; });
window.addEventListener('keyup', (e) => { keys[e.key] = false; });

canvas.addEventListener('mousemove', (e) => {
  if (!isPlaying) return;
  const rect = canvas.getBoundingClientRect();
  player.x = e.clientX - rect.left;
});

function startGame() {
  isPlaying = true;
  score = 0;
  scoreVal.textContent = '0';
  dodgeballs = [];
  items = [];
  player.x = canvas.width / 2;
  overlay.style.display = 'none';
  requestAnimationFrame(gameLoop);
}

function spawnDodgeball() {
  const radius = 12 + Math.random() * 8;
  dodgeballs.push({
    x: Math.random() * (canvas.width - radius * 2) + radius,
    y: -radius,
    radius: radius,
    speedY: 3 + Math.random() * 3 + (score / 150),
    speedX: (Math.random() - 0.5) * 2
  });
}

function spawnItem() {
  const type = Math.random() > 0.3 ? 'whistle' : 'sneaker';
  items.push({
    x: Math.random() * (canvas.width - 30) + 15,
    y: -20,
    type: type,
    speed: 2.5
  });
}

function gameLoop() {
  if (!isPlaying) return;
  frameCount++;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Gym Court Markings
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 80, 0, Math.PI * 2);
  ctx.moveTo(0, canvas.height / 2);
  ctx.lineTo(canvas.width, canvas.height / 2);
  ctx.stroke();

  // Player movement keyboard handling
  if (keys['ArrowLeft'] || keys['a'] || keys['A']) player.x -= player.speed;
  if (keys['ArrowRight'] || keys['d'] || keys['D']) player.x += player.speed;

  // Keep player inside canvas boundary
  player.x = Math.max(player.radius, Math.min(canvas.width - player.radius, player.x));

  // Draw Player (Eagle Student)
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#f8fafc';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Spawn obstacles & items
  if (frameCount % Math.max(20, 60 - Math.floor(score / 50)) === 0) {
    spawnDodgeball();
  }
  if (frameCount % 180 === 0) {
    spawnItem();
  }

  // Update & Draw Dodgeballs
  for (let i = dodgeballs.length - 1; i >= 0; i--) {
    let b = dodgeballs[i];
    b.y += b.speedY;
    b.x += b.speedX;

    ctx.fillStyle = '#ef4444';
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#991b1b';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Collision check with player
    let dist = Math.hypot(player.x - b.x, player.y - b.y);
    if (dist < player.radius + b.radius) {
      gameOver();
      return;
    }

    if (b.y > canvas.height + b.radius) {
      dodgeballs.splice(i, 1);
      score += 10;
      scoreVal.textContent = score;
    }
  }

  // Update & Draw Collectible Items
  for (let i = items.length - 1; i >= 0; i--) {
    let item = items[i];
    item.y += item.speed;

    ctx.font = '20px sans-serif';
    ctx.fillText(item.type === 'whistle' ? '🦺' : '👟', item.x - 10, item.y);

    let dist = Math.hypot(player.x - item.x, player.y - item.y);
    if (dist < player.radius + 15) {
      if (item.type === 'whistle') score += 50;
      if (item.type === 'sneaker') score += 100;
      scoreVal.textContent = score;
      items.splice(i, 1);
      continue;
    }

    if (item.y > canvas.height + 20) {
      items.splice(i, 1);
    }
  }

  requestAnimationFrame(gameLoop);
}

function gameOver() {
  isPlaying = false;
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('eagle_pe_high', highScore);
    highScoreVal.textContent = highScore;
  }
  document.getElementById('overlayTitle').textContent = 'Game Over!';
  document.getElementById('overlayDesc').innerHTML = 'You got hit by a dodgeball!<br/>Final Score: <strong style="color:#38bdf8;">' + score + '</strong>';
  document.getElementById('startBtn').textContent = 'Play Again';
  overlay.style.display = 'flex';
}
